// ПЛК-локации для elevator_mini.takt
//
// Внешняя карта адресов (фича 0020) для цели st-at: держит ПЛК-локации
// ОТДЕЛЬНО от модели. Сама модель не правится — она корректна для целей
// c/c-hal; под ПЛК адреса переопределяются здесь (приоритет: inline <
// address < внешняя карта).
//
// Класс локации (%I / %Q) генератор берёт из направления порта, поэтому
// входы и выходы нумеруются независимо. Для bit-порта адрес — номер БАЙТА,
// а бит — позиция в нём: 8 портов на байт.
//

// ── Входы → %IX ──
elevator_motor_sensor_u = 0x0:0;
elevator_motor_sensor_d = 0x0:1;
floor_button_f1 = 0x0:2;
floor_button_f2 = 0x0:3;
floor_button_f3 = 0x0:4;
floor_button_f4 = 0x0:5;
floor_button_f5 = 0x0:6;
floor_button_f6 = 0x0:7;
floor_button_f7 = 0x1:0;
floor_button_f8 = 0x1:1;
floor_button_f9 = 0x1:2;
floor_sensor_f1_top = 0x1:3;
floor_sensor_f1_bottom = 0x1:4;
floor_sensor_f2_top = 0x1:5;
floor_sensor_f2_bottom = 0x1:6;
floor_sensor_f3_top = 0x1:7;
floor_sensor_f3_bottom = 0x2:0;
floor_sensor_f4_top = 0x2:1;
floor_sensor_f4_bottom = 0x2:2;
floor_sensor_f5_top = 0x2:3;
floor_sensor_f5_bottom = 0x2:4;
floor_sensor_f6_top = 0x2:5;
floor_sensor_f6_bottom = 0x2:6;
floor_sensor_f7_top = 0x2:7;
floor_sensor_f7_bottom = 0x3:0;
floor_sensor_f8_top = 0x3:1;
floor_sensor_f8_bottom = 0x3:2;
floor_sensor_f9_top = 0x3:3;
floor_sensor_f9_bottom = 0x3:4;
cabin_button_f1 = 0x3:5;
cabin_button_f2 = 0x3:6;
cabin_button_f3 = 0x3:7;
cabin_button_f4 = 0x4:0;
cabin_button_f5 = 0x4:1;
cabin_button_f6 = 0x4:2;
cabin_button_f7 = 0x4:3;
cabin_button_f8 = 0x4:4;
cabin_button_f9 = 0x4:5;
cabin_button_do = 0x4:6;
cabin_button_dc = 0x4:7;

// ── Выходы → %QX ──
elevator_motor_up = 0x0:0;
elevator_motor_down = 0x0:1;
elevator_motor_stop = 0x0:2;
door_open = 0x0:3;

